from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        # used[employee][year] -> number of leave days used
        self._used: dict[str, dict[int, int]] = {}

    def _is_workday(self, d: date) -> bool:
        # Weekends (Saturday=5, Sunday=6) and holidays are not leave days
        return d.weekday() < 5 and d not in self.holidays

    def _count_leave_days(self, start: date, end: date) -> int:
        count = 0
        current = start
        while current <= end:
            if self._is_workday(current):
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date is before start date")

        # Must be requested at least 3 days before the start date
        if (start - today).days < 3:
            raise ValueError("Requests must be made at least 3 days before the start date")

        days_needed = self._count_leave_days(start, end)

        # A request may span multiple years; check capacity per year.
        # Aggregate needed days per year.
        needed_by_year: dict[int, int] = {}
        current = start
        while current <= end:
            if self._is_workday(current):
                needed_by_year[current.year] = needed_by_year.get(current.year, 0) + 1
            current += timedelta(days=1)

        for year, needed in needed_by_year.items():
            if self.remaining(employee, year) < needed:
                raise ValueError(
                    f"Insufficient leave days remaining in {year}: "
                    f"needed {needed}, remaining {self.remaining(employee, year)}"
                )

        # Commit the usage
        emp_used = self._used.setdefault(employee, {})
        for year, needed in needed_by_year.items():
            emp_used[year] = emp_used.get(year, 0) + needed

        return days_needed

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get(employee, {}).get(year, 0)
        # Unused leave does not carry over: cap at 0
        return max(0, self.days_per_year - used)
